# not done, 0 = no bound. Our own bound's push never counts: bound() clears wasFalling and marks the landing done.
M(monk, r"""
public static int spikeKind(boolean chain, int move, boolean wasFalling, boolean boundDone, double vy, double prevVy, double jf, long sinceLand, long after, boolean nearGround) {
  if (!chain || move != 0) return 0;
  double lim = jf > 0.0 ? 0.5 * jf : 5.9;
  if (!(vy > lim) || prevVy > lim) return 0;
  if (wasFalling && nearGround) return 2;          // review: a missed landing only - never a jump pad / knockback / pull / Double Jump in mid-air
  if (!boundDone && sinceLand >= 0L && sinceLand <= after) return 1;
  return 0;
}""")
# the flowing fall: the speed t ms after the top under (1 - pct) x g (never upward)
''')
rep('''# the stunlock's boss words (Stun.bossRole's rule: a WHOLE part of the role name split at _) - a boss is hit but never lifted
''', '''# 0.1.35 (beta bug 6): no Monk hit through blocks. true = no SOLID block (TravGrid 1) between a and b, sampled every 0.25 block; the start and
# end blocks are skipped (your own / the enemy's), an unreadable block (-1) and plants / fluids (0) never cost a hit
M(monk, r"""
public static boolean rayOpen(@PKG@.TravGrid g, double ax, double ay, double az, double bx, double by, double bz) {
  if (g == null) return true;
  double dx = bx - ax;
  double dy = by - ay;
  double dz = bz - az;
  double l = Math.sqrt(dx * dx + dy * dy + dz * dz);
  if (!(l > 1.0E-6) || Double.isInfinite(l)) return true;
  int n = (int) Math.ceil(l / 0.25);
  if (n > 512) n = 512;
  int x0 = (int) Math.floor(ax);
  int y0 = (int) Math.floor(ay);
  int z0 = (int) Math.floor(az);
  int x1 = (int) Math.floor(bx);
  int y1 = (int) Math.floor(by);
  int z1 = (int) Math.floor(bz);
  for (int k = 1; k < n; k++) {
    double u = (double) k / (double) n;
    int x = (int) Math.floor(ax + dx * u);
    int y = (int) Math.floor(ay + dy * u);
    int z = (int) Math.floor(az + dz * u);
    if ((x == x0 && y == y0 && z == z0) || (x == x1 && y == y1 && z == z1)) continue;
    if (g.at(x, y, z) == 1) return false;
  }
  return true;
}""")
# an enemy (feet t, height th) is seen from a when the line to its middle OR to near its top is open
M(monk, r"""
public static boolean seesT(@PKG@.TravGrid g, double ax, double ay, double az, double tx, double ty, double tz, double th) {
  if (g == null) return true;
  double h = th > 0.2 ? th : 1.0;
  if (rayOpen(g, ax, ay, az, tx, ty + h * 0.5, tz)) return true;
  return rayOpen(g, ax, ay, az, tx, ty + h * 0.85, tz);
}""")
