M(monk, r"""
public static boolean nearGround(@CB@ buf, @VEC@ p, double prevVy) {
  if (p == null) return false;
  @PKG@.TravGrid g = null;
  try { g = @PKG@.ArmoryTrav.grid(@PKG@.ArmoryTrav.worldOf(buf)); } catch (Throwable t) { g = null; }
  int unk = 0;
  if (g != null) {
    for (int k = 0; k < 3; k++) {
      int v = g.at((int) Math.floor(p.x), (int) Math.floor(p.y - 0.2 - 0.5 * (double) k), (int) Math.floor(p.z));
      if (v == 1) return true;
      if (v < 0) unk++;
    }
  } else unk = 3;
  return unk == 3 && prevVy >= -5.0 && prevVy <= 0.5;
}""")
